package com.scamshield.le.data.repository
import android.content.Context; import android.content.Intent; import android.net.Uri
import com.scamshield.le.data.model.ScamReport; import javax.inject.Inject; import javax.inject.Singleton
@Singleton class ReportRepository @Inject constructor(private val context: Context) {
    fun reportToFTC(report: ScamReport) = openUrl("https://reportfraud.ftc.gov/#/")
    fun reportToIC3(report: ScamReport) = openUrl("https://www.ic3.gov/Home/FileComplaint")
    fun reportToSSA(report: ScamReport) = openUrl("https://oig.ssa.gov/report/")
    fun generateReportSummary(report: ScamReport): String {
        val sb = StringBuilder()
        sb.appendLine("=== ScamShield LE — Incident Report ===")
        sb.appendLine("Date: ${java.text.SimpleDateFormat("MMM d, yyyy h:mm a", java.util.Locale.getDefault()).format(java.util.Date(report.timestamp))}")
        sb.appendLine("Risk Score: ${report.riskScore}/100"); sb.appendLine()
        sb.appendLine("DETECTED SIGNALS:"); report.signalsDetected.forEach { sb.appendLine("  • $it") }; sb.appendLine()
        if (report.callerClaimed.isNotBlank()) sb.appendLine("CALLER CLAIMED TO BE: ${report.callerClaimed}")
        if (report.paymentRequested) { sb.appendLine("PAYMENT REQUESTED: Yes"); if (report.paymentMethod.isNotBlank()) sb.appendLine("  Method: ${report.paymentMethod}"); if (report.amountRequested.isNotBlank()) sb.appendLine("  Amount: ${report.amountRequested}") }
        if (report.phoneNumber.isNotBlank()) sb.appendLine("CALLER PHONE NUMBER: ${report.phoneNumber}")
        sb.appendLine(); sb.appendLine("TRANSCRIPT EXCERPT:"); sb.appendLine(report.transcript.take(500) + if (report.transcript.length > 500) "..." else "")
        sb.appendLine(); sb.appendLine("Generated by ScamShield LE"); return sb.toString()
    }
    fun shareReport(report: ScamReport) { val summary = generateReportSummary(report); val intent = Intent(Intent.ACTION_SEND).apply { type = "text/plain"; putExtra(Intent.EXTRA_SUBJECT, "ScamShield LE — Scam Incident Report"); putExtra(Intent.EXTRA_TEXT, summary); flags = Intent.FLAG_ACTIVITY_NEW_TASK }; context.startActivity(Intent.createChooser(intent, "Share Incident Report").apply { flags = Intent.FLAG_ACTIVITY_NEW_TASK }) }
    fun callAgency(phoneNumber: String) { val intent = Intent(Intent.ACTION_DIAL, U[i.parse("tel:$phoneNumber")).apply { flags = Intent.FLAG_ACTIVITY_NEW_TASK }; context.startActivity(intent) }
    private fun openUrl(url: String) { val intent = Intent(Intent.ACTION_VIEW, Uri.parse(url)).apply { flags = Intent.FLAG_ACTIVITY_NEW_TASK }; context.startActivity(intent) }
}
